import java.sql.*;
import java.util.ArrayList;

public class StudentDB {
    private final String url = "jdbc:mysql://localhost:3306/school";
    private final String user = "root", pass = "yourPassword";

    public boolean insert(int id, String name, int age, double gpa) {
        String sql = "INSERT INTO students (id, name, age, gpa) VALUES (?, ?, ?, ?)";
        try (Connection c = DriverManager.getConnection(url, user, pass);
             PreparedStatement ps = c.prepareStatement(sql)) {
            ps.setInt(1, id); ps.setString(2, name); ps.setInt(3, age); ps.setDouble(4, gpa);
            ps.executeUpdate();
            return true;
        } catch (SQLException e) { return false; }
    }

    public ArrayList<String> names() {
        ArrayList<String> out = new ArrayList<>();
        try (Connection c = DriverManager.getConnection(url, user, pass);
             Statement st = c.createStatement();
             ResultSet rs = st.executeQuery("SELECT name FROM students")) {
            while (rs.next()) out.add(rs.getString("name"));
        } catch (SQLException e) { System.out.println(e.getMessage()); }
        return out;
    }
}

